  if (!render) {
    return { promptId: "", status: "error", error: "\u8BF7\u5148\u5728\u8282\u70B9\u5F39\u7A97\u4E2D\u6446\u706F\u5E76\u751F\u6210\u53C2\u8003\u56FE\u3002", entries: [] };
  }
